  quiz: [
    lQ(['OSPF runs directly over IP. Which protocol number?', 'OSPF работает прямо поверх IP. Какой номер протокола?', 'OSPF רץ ישירות מעל IP. איזה מספר פרוטוקול?'], ['89', '88', '6', '17'], 0,
      ['IP protocol 89 — not TCP (6) and not UDP (17). EIGRP is 88.', 'IP-протокол 89 — не TCP (6) и не UDP (17). У EIGRP — 88.', 'פרוטוקול IP ‏89 — לא TCP ‏(6) ולא UDP ‏(17). ל-EIGRP ‏88.']),
    lQ(['Which multicast address do only the DR and the BDR listen to?', 'Какой multicast-адрес слушают только DR и BDR?', 'לאיזו כתובת multicast מאזינים רק ה-DR וה-BDR?'], ['224.0.0.6', '224.0.0.5', '224.0.0.9', '224.0.0.10'], 0,
      ['DROTHERs send changes to 224.0.0.6; the DR repeats them to all OSPF routers on 224.0.0.5.', 'DROTHER шлют изменения на 224.0.0.6; DR пересылает их всем OSPF-роутерам на 224.0.0.5.', 'DROTHER שולחים שינויים ל-224.0.0.6; ה-DR מעביר אותם לכל נתבי ה-OSPF ב-224.0.0.5.']),
    lQ(['An OSPF adjacency is stuck in ExStart/Exchange. Most likely cause?', 'OSPF-соседство зависло в ExStart/Exchange. Самая вероятная причина?', 'שכנות OSPF נתקעה ב-ExStart/Exchange. הסיבה הסבירה ביותר?'],
      [['Different MTU on the two ends', 'Разный MTU на концах', 'MTU שונה בשני הצדדים'], ['Different process ID', 'Разный process ID', 'process ID שונה'], ['Different priority', 'Разный priority', 'priority שונה'], ['A passive interface', 'Пассивный интерфейс', 'ממשק פסיבי']], 0,
      ['Hellos pass, but the DBD exchange fails when the MTUs differ.', 'Hello проходят, но обмен DBD ломается, когда MTU разный.', 'ה-Hello עוברים, אבל החלפת ה-DBD נכשלת כשה-MTU שונה.']),
    lQ(['Two routers on an Ethernet segment show each other as 2WAY/DROTHER. What is it?', 'Два роутера в Ethernet-сегменте видят друг друга как 2WAY/DROTHER. Что это?', 'שני נתבים בסגמנט Ethernet רואים זה את זה כ-2WAY/DROTHER. מה זה?'],
      [['Normal: DROTHERs become FULL only with the DR and BDR', 'Норма: DROTHER доходят до FULL только с DR и BDR', 'תקין: DROTHER מגיעים ל-FULL רק עם DR ו-BDR'], ['An MTU mismatch', 'Разный MTU', 'MTU שונה'], ['A timer mismatch', 'Разные таймеры', 'טיימרים שונים'], ['Duplicate router IDs', 'Одинаковые router ID', 'router ID כפולים']], 0,
      ['2-Way between two DROTHERs is the expected final state.', '2-Way между двумя DROTHER — ожидаемое конечное состояние.', '2-Way בין שני DROTHER הוא המצב הסופי הצפוי.']),
    lQ(['Which LSA type does the DR create for its segment?', 'Какой тип LSA создаёт DR для своего сегмента?', 'איזה סוג LSA יוצר ה-DR עבור הסגמנט שלו?'],
      [['Type 2 — Network LSA', 'Тип 2 — Network LSA', 'סוג 2 — Network LSA'], ['Type 1 — Router LSA', 'Тип 1 — Router LSA', 'סוג 1 — Router LSA'], ['Type 3 — Summary LSA', 'Тип 3 — Summary LSA', 'סוג 3 — Summary LSA'], ['Type 5 — External LSA', 'Тип 5 — External LSA', 'סוג 5 — External LSA']], 0,
      ['Type 1 — every router; 2 — DR; 3 — ABR; 5 — ASBR.', 'Тип 1 — каждый роутер; 2 — DR; 3 — ABR; 5 — ASBR.', 'סוג 1 — כל נתב; 2 — DR; ‏3 — ABR; ‏5 — ASBR.']),
    lQ(['Ten routers on one Ethernet segment, each FULL with each (no DR). How many adjacencies?', 'Десять роутеров в одном Ethernet-сегменте, каждый FULL с каждым (без DR). Сколько смежностей?', 'עשרה נתבים בסגמנט Ethernet אחד, כל אחד FULL עם כל אחד (בלי DR). כמה סמיכויות?'], ['45', '10', '90', '20'], 0,
      ['n(n−1)/2 = 10·9/2 = 45 — that is why OSPF elects a DR.', 'n(n−1)/2 = 10·9/2 = 45 — поэтому OSPF и выбирает DR.', 'n(n−1)/2 = 10·9/2 = 45 — בגלל זה OSPF בוחר DR.']),
    lQ(['Which packet carries the LSAs themselves?', 'Какой пакет несёт сами LSA?', 'איזו חבילה נושאת את ה-LSA עצמם?'], ['LSU', 'DBD', 'LSR', 'LSAck'], 0,
      ['DBD — table of contents, LSR — request, LSU — the LSAs, LSAck — acknowledgement.', 'DBD — оглавление, LSR — запрос, LSU — сами LSA, LSAck — подтверждение.', 'DBD — תוכן עניינים, LSR — בקשה, LSU — ה-LSA, ‏LSAck — אישור.']),
    lQ(['What does "O IA" mean in the routing table?', 'Что значит "O IA" в таблице маршрутизации?', 'מה המשמעות של "O IA" בטבלת הניתוב?'],
      [['An OSPF route from another area', 'OSPF-маршрут из другой области', 'נתיב OSPF מאזור אחר'], ['An external route type 2', 'Внешний маршрут типа 2', 'נתיב חיצוני מסוג 2'], ['A route inside your area', 'Маршрут внутри своей области', 'נתיב בתוך האזור שלך'], ['An inactive route', 'Неактивный маршрут', 'נתיב לא פעיל']], 0,
      ['IA = inter-area, learned from a Summary LSA (type 3) of an ABR.', 'IA — inter-area, получен из Summary LSA (тип 3) от ABR.', 'IA = inter-area, נלמד מ-Summary LSA ‏(סוג 3) של ABR.']),
    lQ(['Which value does NOT have to match for two routers to become OSPF neighbours?', 'Что НЕ обязано совпадать, чтобы два роутера стали OSPF-соседями?', 'מה לא חייב להיות זהה כדי ששני נתבים יהיו שכני OSPF?'],
      [['The process ID', 'Process ID', 'ה-process ID'], ['The area', 'Area', 'ה-area'], ['Hello/Dead timers', 'Таймеры Hello/Dead', 'טיימרי Hello/Dead'], ['The subnet mask', 'Маска подсети', 'מסכת תת-הרשת']], 0,
      ['The process ID is local to the router — a classic trick question.', 'Process ID локален для роутера — классический вопрос с подвохом.', 'ה-process ID מקומי לנתב — שאלה מכשילה קלאסית.']),
  ],
